-- Ventas de vestidos: consecutivo del comprobante, datos para imprimirlo, número de factura de Siigo, y ventas sumadas en Metas y Ventas.
-- Reversión: alter table public.ventas_vestidos drop column consecutivo; drop function public.venta_comprobante(uuid), private.venta_comprobante(uuid),
--   public.venta_numero_factura(uuid,text), private.venta_numero_factura(uuid,text); y volver private.metas_panel a 20261218120000.
alter table public.ventas_vestidos add column if not exists consecutivo bigint generated by default as identity;

create or replace function private.venta_comprobante(p_id uuid)
 returns jsonb language sql stable security definer set search_path to ''
as $function$
 select jsonb_build_object('id',s.id,'consecutivo',s.consecutivo,'fecha',s.fecha,'created_at',s.created_at,'estado',s.estado,'motivo_anulacion',s.motivo_anulacion,
  'precio_lista',s.precio_lista,'descuento',s.descuento,'motivo_descuento',s.motivo_descuento,'total',s.total,'medio_pago',s.medio_pago,
  'cliente_nombre',s.cliente_nombre,'cliente_documento',s.cliente_documento,'cliente_telefono',s.cliente_telefono,'cliente_email',s.cliente_email,
  'numero_factura',s.numero_factura,'codigo_siigo',s.codigo_siigo,'siigo_estado',s.siigo_estado,
  'vestido',jsonb_build_object('codigo',v.codigo,'nombre',v.nombre,'talla',v.talla,'color',v.color,'tipo',k.nombre),
  'sede',jsonb_build_object('nombre',d.nombre,'direccion',coalesce(d.direccion_clientes,d.direccion),'telefono',d.telefono),
  'vendedor',(select coalesce(nombre,email) from public.profiles where id=s.vendedor_id),
  'empresa',(select jsonb_build_object('nit',c.nit,'direccion',c.direccion,'ciudad',c.ciudad,'correo',c.correo,'telefono',c.telefono) from public.aliados_contrato_config c where c.id=1))
 from public.ventas_vestidos s join public.vestidos v on v.id=s.vestido_id left join public.clasificaciones_vestido k on k.id=v.clasificacion_id left join public.sedes d on d.id=s.sede_id
 where s.id=p_id and auth.uid() is not null and (public.es_admin() or private.sedes_limitadas() is null or s.sede_id=any(private.sedes_limitadas()));
$function$;
create or replace function public.venta_comprobante(p_id uuid) returns jsonb language sql stable set search_path to '' as $function$ select private.venta_comprobante(p_id); $function$;

create or replace function private.venta_numero_factura(p_id uuid, p_numero text)
 returns void language plpgsql security definer set search_path to ''
as $function$
declare s public.ventas_vestidos; num text:=nullif(left(btrim(coalesce(p_numero,'')),40),'');
begin
 if not (public.es_admin() or private.tiene_permiso('ventas.registrar')) then raise exception 'No tienes permiso para editar ventas.' using errcode='42501'; end if;
 select * into s from public.ventas_vestidos where id=p_id for update;
 if not found or not (public.es_admin() or private.sedes_limitadas() is null or s.sede_id=any(private.sedes_limitadas())) then raise exception 'Venta no encontrada.'; end if;
 if s.estado<>'registrada' then raise exception 'La venta está anulada.'; end if;
 update public.ventas_vestidos set numero_factura=num where id=p_id;
end $function$;
create or replace function public.venta_numero_factura(p_id uuid, p_numero text) returns void language sql set search_path to '' as $function$ select private.venta_numero_factura(p_id,p_numero); $function$;

revoke all on function private.venta_comprobante(uuid), public.venta_comprobante(uuid), private.venta_numero_factura(uuid,text), public.venta_numero_factura(uuid,text) from public, anon;
grant execute on function private.venta_comprobante(uuid), public.venta_comprobante(uuid), private.venta_numero_factura(uuid,text), public.venta_numero_factura(uuid,text) to authenticated;

-- Metas y Ventas: lo vendido y lo recaudado del mes incluyen las ventas de vestidos (de contado) no anuladas.
create or replace function private.metas_panel(p_sede uuid, p_mes integer, p_anio integer)
 returns jsonb language plpgsql stable security definer set search_path to ''
as $function$
declare limite uuid:=private.metas_sede_usuario(); ini date:=make_date(p_anio,p_mes,1); fin date; hoy date:=(now() at time zone 'America/Bogota')::date; ref date;
begin
 if auth.uid() is null or private.prov_rol() in ('','proveedor') then raise exception 'No autorizado.' using errcode='42501'; end if;
 fin:=(ini+interval '1 month -1 day')::date;
 ref:=least(greatest(hoy,ini),fin+1);
 return coalesce((select jsonb_agg(x order by x->>'sede') from (
  select jsonb_build_object('sede_id',s.id,'sede',s.nombre,'meta_id',m.id,'meta',m.monto_meta,'automatica',coalesce(m.automatica,false),
   'dias_operativos',coalesce(m.dias_operativos,private.dias_operativos(ini,fin)),'dias_calculados',private.dias_operativos(ini,fin),
   'dias_restantes',case when ref>fin then 0 else private.dias_operativos(ref,fin) end,
   'vendido',v.total+w.total,'vendido_hasta_ayer',v.hasta_ayer+w.hasta_ayer,'contratos',v.n,'ventas',w.n,'ventas_valor',w.total,
   'recaudado_mes',(select coalesce(sum(p.valor_pagado),0) from public.pagos p join public.contratos c on c.id=p.contrato_id
     where c.sede_id=s.id and p.anulado_at is null and (p.fecha_pago at time zone 'UTC')::date between ini and fin and lower(coalesce(c.estado,'')) not in ('cancelado','anulado','borrador','rechazado'))+w.total) x
  from public.sedes s
  left join lateral (select * from public.metas x where x.tipo='sede' and x.mes=p_mes and x.anio=p_anio and (x.identificador_id=s.id or private.norm_nombre(x.nombre_objetivo)=private.norm_nombre(s.nombre)) order by x.identificador_id nulls last limit 1) m on true
  cross join lateral (select coalesce(sum(c.valor_total),0) total,coalesce(sum(c.valor_total) filter (where (c.created_at at time zone 'America/Bogota')::date<ref),0) hasta_ayer,count(*) n
   from public.contratos c where c.sede_id=s.id and (c.created_at at time zone 'America/Bogota')::date between ini and fin and lower(coalesce(c.estado,'')) not in ('cancelado','anulado','borrador','rechazado')) v
  cross join lateral (select coalesce(sum(t.total),0) total,coalesce(sum(t.total) filter (where t.fecha<ref),0) hasta_ayer,count(*) n
   from public.ventas_vestidos t where t.sede_id=s.id and t.estado='registrada' and t.fecha between ini and fin) w
  where coalesce(s.activo,true) and (limite is null or s.id=limite) and (p_sede is null or s.id=p_sede)) t(x)),'[]'::jsonb);
end $function$;
